-- Trick or Treat (docs/29). Generated by `tsx scripts/patch-hh-trick-or-treat.ts --sql`: do not edit by hand.
-- Patches only what it adds, over the admin's later edits: game_config `trickOrTreat` (its switch Off, its numbers,
-- Haunted Hollow's ghost lists; an admin's row keeps its values and own lists), one Trick or Treat card in each of
-- the world's ten main areas (an area whose deck already counts them keeps its number), and trick_or_treat_open(),
-- the switch as the server reads it for the caller (docs/15 §20). Then `configVersion` + 1. Safe to run again.
begin;
insert into game_config (key, value) values ('trickOrTreat', '{"access":"off","treatMin":10,"treatMax":30,"failPush":35,"tiers":{"common":{"weight":6,"flee":90,"sections":[{"from":0,"need":6},{"from":40,"need":5},{"from":75,"need":4},{"from":80,"need":3}]},"rare":{"weight":3,"flee":85,"sections":[{"from":0,"need":6},{"from":40,"need":5},{"from":75,"need":4}]},"veryRare":{"weight":1,"flee":65,"sections":[{"from":0,"need":6},{"from":45,"need":5}]}},"areas":{"c3da0041-6de3-5997-8243-ab9b3559f166":[{"dex":425,"tier":"rare"},{"dex":92,"tier":"veryRare"}],"be8feb03-b0a9-57e8-b720-8efb8158be5f":[{"dex":92,"tier":"common"},{"dex":622,"tier":"rare"}],"6bf5cdc8-d9a0-5222-867a-a9b955f0d3d2":[{"dex":708,"tier":"common"},{"dex":710,"tier":"common"},{"dex":946,"tier":"common"}],"45c379ef-71bc-58cc-a268-a59aaf818f6f":[{"dex":607,"tier":"common"},{"dex":353,"tier":"common"},{"dex":200,"tier":"veryRare"}],"8a531ee2-3eae-5340-89e5-489e482f0728":[{"dex":622,"tier":"common"}],"baf5ef53-0f38-53ca-841b-38f81e77cc54":[{"dex":353,"tier":"common"},{"dex":355,"tier":"common"},{"dex":478,"tier":"veryRare"}],"4b5f0177-dcfe-5760-99c1-57b26089f2be":[{"dex":769,"tier":"common"}],"a83d3d74-c03b-5d9c-9e72-0be42242b332":[{"dex":679,"tier":"common"},{"dex":680,"tier":"veryRare"}],"974c4771-faf0-5c54-a203-14cac004d652":[{"dex":425,"tier":"common"},{"dex":426,"tier":"rare"},{"dex":947,"tier":"rare"}],"19d09269-ac38-5bd3-bad9-cafbb9a9d9c4":[{"dex":355,"tier":"common"},{"dex":200,"tier":"common"},{"dex":354,"tier":"common"},{"dex":356,"tier":"rare"}]}}'::jsonb)
on conflict (key) do nothing;
update game_config set value = jsonb_set(value, '{areas}', '{"c3da0041-6de3-5997-8243-ab9b3559f166":[{"dex":425,"tier":"rare"},{"dex":92,"tier":"veryRare"}],"be8feb03-b0a9-57e8-b720-8efb8158be5f":[{"dex":92,"tier":"common"},{"dex":622,"tier":"rare"}],"6bf5cdc8-d9a0-5222-867a-a9b955f0d3d2":[{"dex":708,"tier":"common"},{"dex":710,"tier":"common"},{"dex":946,"tier":"common"}],"45c379ef-71bc-58cc-a268-a59aaf818f6f":[{"dex":607,"tier":"common"},{"dex":353,"tier":"common"},{"dex":200,"tier":"veryRare"}],"8a531ee2-3eae-5340-89e5-489e482f0728":[{"dex":622,"tier":"common"}],"baf5ef53-0f38-53ca-841b-38f81e77cc54":[{"dex":353,"tier":"common"},{"dex":355,"tier":"common"},{"dex":478,"tier":"veryRare"}],"4b5f0177-dcfe-5760-99c1-57b26089f2be":[{"dex":769,"tier":"common"}],"a83d3d74-c03b-5d9c-9e72-0be42242b332":[{"dex":679,"tier":"common"},{"dex":680,"tier":"veryRare"}],"974c4771-faf0-5c54-a203-14cac004d652":[{"dex":425,"tier":"common"},{"dex":426,"tier":"rare"},{"dex":947,"tier":"rare"}],"19d09269-ac38-5bd3-bad9-cafbb9a9d9c4":[{"dex":355,"tier":"common"},{"dex":200,"tier":"common"},{"dex":354,"tier":"common"},{"dex":356,"tier":"rare"}]}'::jsonb
  || case when jsonb_typeof(value -> 'areas') = 'object' then value -> 'areas' else '{}'::jsonb end)
where key = 'trickOrTreat' and jsonb_typeof(value) = 'object';
update areas set encounter_weights = coalesce(encounter_weights, '{}'::jsonb) || '{"trick": 1}'::jsonb
where id in ('c3da0041-6de3-5997-8243-ab9b3559f166', 'be8feb03-b0a9-57e8-b720-8efb8158be5f', '6bf5cdc8-d9a0-5222-867a-a9b955f0d3d2', '45c379ef-71bc-58cc-a268-a59aaf818f6f', '8a531ee2-3eae-5340-89e5-489e482f0728', 'baf5ef53-0f38-53ca-841b-38f81e77cc54', '4b5f0177-dcfe-5760-99c1-57b26089f2be', 'a83d3d74-c03b-5d9c-9e72-0be42242b332', '974c4771-faf0-5c54-a203-14cac004d652', '19d09269-ac38-5bd3-bad9-cafbb9a9d9c4')
  and not (coalesce(encounter_weights, '{}'::jsonb) ? 'trick');
-- The switch for the caller: on for everyone, or for the admin only (their JWT). An odd value is off.
create or replace function trick_or_treat_open()
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(a = 'all' or (a = 'admin' and is_admin()), false)
  from (select coalesce((select value ->> 'access' from game_config where key = 'trickOrTreat' and jsonb_typeof(value) = 'object'), 'off') a) x
$$;
revoke all on function trick_or_treat_open() from public;
grant execute on function trick_or_treat_open() to anon, authenticated;
insert into game_config (key, value) values ('configVersion', '1'::jsonb) on conflict (key) do update set value = to_jsonb(coalesce((game_config.value #>> '{}')::int, 0) + 1);
commit;
